-- Synthetic-only disposable PostgreSQL17 database. Never run against a real account.
CREATE TABLE public.accounts(id uuid PRIMARY KEY,user_id uuid NOT NULL,institution text,balance numeric,currency text);
CREATE TABLE public.financial_events(id uuid PRIMARY KEY,user_id uuid NOT NULL,account_id uuid REFERENCES public.accounts(id),legacy_id text,legacy_index integer,event_date date NOT NULL,description_raw text,description_normalized text,amount numeric NOT NULL,nature text,category text,counterparty text,source text NOT NULL,status text NOT NULL,is_internal_transfer boolean NOT NULL DEFAULT false,is_projection boolean NOT NULL DEFAULT false,is_suppressed boolean NOT NULL DEFAULT false,suppression_reason text,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,legacy_id));
CREATE TABLE public.lts_open_finance_staging(id uuid PRIMARY KEY,user_id uuid NOT NULL,resource_type text,institution_code text,provider_account_ref text,provider_record_id text,connection_id uuid,currency text,posting_date date,signed_amount numeric,description_raw text,raw_hash text,raw_payload jsonb,normalized_payload jsonb,provider_deleted_at timestamptz,sync_run_id uuid,last_seen_at timestamptz,updated_at timestamptz);
CREATE TABLE public.lts_v178_review_decision(user_id uuid NOT NULL,source_table text NOT NULL,source_ref text NOT NULL,category_label text,property_code text,beneficiary text,decision_basis text NOT NULL,decided_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,source_table,source_ref));
CREATE TABLE public.lts_reconciliation_link(id bigserial PRIMARY KEY,user_id uuid NOT NULL,target_event_id uuid NOT NULL REFERENCES public.financial_events(id),candidate_source_table text NOT NULL,candidate_source_ref text NOT NULL,candidate_event_date date NOT NULL,candidate_amount numeric NOT NULL,note text,confirmed_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,target_event_id));
CREATE TABLE public.lts_flow_event_operation(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,target_event_id uuid NOT NULL CONSTRAINT lts_flow_event_operation_target_event_id_fkey REFERENCES public.financial_events(id),operation text);
CREATE TABLE public.lts_access_audit(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id uuid,email text,action text,meta jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.lts_read_cache_epoch_v242(singleton boolean PRIMARY KEY,epoch bigint NOT NULL);
CREATE TABLE public.lts_v229_read_cache(user_id uuid NOT NULL,payload jsonb);
-- Faithful relevant branch for the three mutated tables: transition-table changed detection, epoch then cache.
CREATE FUNCTION public.lts_v246_invalidate_finance_cache() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $f$
DECLARE changed boolean:=false;
BEGIN
 IF TG_OP='INSERT' THEN SELECT EXISTS(SELECT 1 FROM new_rows) INTO changed;
 ELSIF TG_OP='DELETE' THEN SELECT EXISTS(SELECT 1 FROM old_rows) INTO changed;
 ELSE SELECT EXISTS((SELECT to_jsonb(n) FROM new_rows n EXCEPT ALL SELECT to_jsonb(o) FROM old_rows o)
  UNION ALL (SELECT to_jsonb(o) FROM old_rows o EXCEPT ALL SELECT to_jsonb(n) FROM new_rows n)) INTO changed;
 END IF;
 IF changed THEN UPDATE public.lts_read_cache_epoch_v242 SET epoch=epoch+1 WHERE singleton=true;
 DELETE FROM public.lts_v229_read_cache WHERE user_id IS NOT NULL; END IF;
 RETURN NULL;
END $f$;
DO $f$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['financial_events','lts_reconciliation_link','lts_v178_review_decision'] LOOP
 EXECUTE format('CREATE TRIGGER cache_i AFTER INSERT ON public.%I REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.lts_v246_invalidate_finance_cache()',t);
 EXECUTE format('CREATE TRIGGER cache_u AFTER UPDATE ON public.%I REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.lts_v246_invalidate_finance_cache()',t);
 EXECUTE format('CREATE TRIGGER cache_d AFTER DELETE ON public.%I REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION public.lts_v246_invalidate_finance_cache()',t);
 END LOOP; END $f$;
CREATE FUNCTION public.lts_bank_known_classification_v231(uuid,uuid) RETURNS jsonb LANGUAGE sql STABLE AS $f$ SELECT jsonb_build_object('category',d.category_label,'property_code',d.property_code,'beneficiary',d.beneficiary) FROM public.lts_v178_review_decision d WHERE d.user_id=$1 AND d.source_ref=$2::text AND d.source_table='lts_open_finance_staging' $f$;
CREATE FUNCTION public.lts_expense_rows_v230_baseline(uuid,date,date) RETURNS TABLE(source_ref text,amount numeric,posting_date date,category text,property_code text,beneficiary text,identity_status text,property_component text) LANGUAGE sql STABLE AS $f$ SELECT s.id::text,-s.signed_amount,s.posting_date,coalesce(d.category_label,'Unclassified'),d.property_code,d.beneficiary,CASE WHEN d.source_ref IS NULL THEN 'pending' ELSE 'identified' END,CASE WHEN d.property_code='synthetic_property' THEN 'Synthetic property tax' ELSE NULL END FROM public.lts_open_finance_staging s LEFT JOIN public.lts_v178_review_decision d ON d.user_id=s.user_id AND d.source_table='lts_open_finance_staging' AND d.source_ref=s.id::text WHERE s.user_id=$1 AND s.normalized_payload->>'status'='POSTED' AND s.posting_date BETWEEN $2 AND $3 $f$;
CREATE FUNCTION public.lts_v229_expense_rows(uuid,date,date) RETURNS TABLE(source_ref text,amount numeric,posting_date date,category text,property_code text,beneficiary text,identity_status text,property_component text) LANGUAGE sql STABLE AS $f$ SELECT * FROM public.lts_expense_rows_v230_baseline($1,$2,$3) $f$;
CREATE FUNCTION public.lts_corrected_cashflow_fix86_v1_engine_v247(uuid,date,date) RETURNS numeric LANGUAGE sql STABLE AS $f$ SELECT coalesce(sum(amount),0) FROM public.financial_events WHERE user_id=$1 AND event_date BETWEEN $2 AND $3 AND NOT is_suppressed $f$;
CREATE FUNCTION public.lts_corrected_cashflow_fix86_v1(uuid,date,date) RETURNS numeric LANGUAGE sql STABLE AS $f$ SELECT public.lts_corrected_cashflow_fix86_v1_engine_v247($1,$2,$3) $f$;
CREATE FUNCTION public.lts_flow_current_effective_v1(uuid,date,date) RETURNS numeric LANGUAGE sql STABLE AS $f$ SELECT public.lts_corrected_cashflow_fix86_v1($1,$2,$3) $f$;
